<?php
declare(strict_types=1);
$root=dirname(__DIR__);$secure=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax']);session_start();
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function jp(string $n):string{global $root;return "$root/data/$n.json";}function R(string $n,array $f=[]):array{$p=jp($n);if(!is_file($p))return $f;$v=json_decode((string)file_get_contents($p),true);return is_array($v)?$v:$f;}function W(string $n,array $d):bool{$j=json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);return $j!==false&&file_put_contents(jp($n),$j.PHP_EOL,LOCK_EX)!==false;}function csrf():string{if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));return $_SESSION['admin_csrf'];}function check_csrf():void{if(!hash_equals((string)($_SESSION['admin_csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('CSRF tekshiruvi muvaffaqiyatsiz.');}
if(isset($_GET['logout'])){$_SESSION=[];session_destroy();header('Location:/admin/index.php');exit;}$pass=(string)(getenv('ADMIN_PASSWORD')?:'');
if(empty($_SESSION['admin'])){$e='';if($_SERVER['REQUEST_METHOD']==='POST'){if($pass!==''&&hash_equals($pass,(string)($_POST['password']??''))){session_regenerate_id(true);$_SESSION['admin']=1;$_SESSION['admin_csrf']=bin2hex(random_bytes(32));header('Location:/admin/index.php');exit;}$e=$pass===''?'ADMIN_PASSWORD sozlanmagan.':'Parol noto‘g‘ri.';}?><!doctype html><html lang="uz"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jahongir Neuro Admin</title><style>body{margin:0;background:#f4f7f5;font:14px Arial;color:#10201c;min-height:100vh;display:grid;place-items:center}.box{width:min(390px,calc(100% - 32px));background:#fff;padding:34px;border-radius:28px;box-shadow:0 30px 90px #0f5c4d18}input,button{width:100%;box-sizing:border-box;padding:14px;border-radius:14px;border:1px solid #dce6e1;margin-top:10px}button{background:#0f5c4d;color:#fff;border:0;font-weight:800}.e{background:#faecec;color:#8b3030;padding:12px;border-radius:12px;margin-top:12px}</style><form class="box" method="post"><b>Jahongir <span style="color:#0f5c4d">Neuro</span></b><h1>Admin panel</h1><p>Kontent, media va murojaatlarni boshqarish.</p><?php if($e):?><div class="e"><?=h($e)?></div><?php endif;?><input type="password" name="password" placeholder="ADMIN_PASSWORD" required autofocus><button>Kirish →</button></form></html><?php exit;}
$tabs=['dashboard'=>'Dashboard','doctor'=>'Doktor','about'=>'About','expertise'=>'Mutaxassislik','portfolio'=>'Portfolio','requests'=>'So‘rovlar','media'=>'Media','settings'=>'Settings'];$tab=$_GET['tab']??'dashboard';if(!isset($tabs[$tab]))$tab='dashboard';$msg='';$err='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';
if($a==='doctor'){$d=R('doctor');foreach(['name','short_name','title','position','clinic','city','academic_degree','experience','bio'] as $k)$d[$k]=trim((string)($_POST[$k]??''));foreach(['operations','experience_cities'] as $k)$d[$k]=array_values(array_filter(array_map('trim',preg_split('/\R/',(string)($_POST[$k]??'')))));if(!W('doctor',$d))throw new RuntimeException('Doctor JSON saqlanmadi.');$msg='Doktor ma’lumotlari saqlandi.';$tab='doctor';}
elseif($a==='about'){$d=R('about');foreach(['title','bio'] as $k)$d[$k]=trim((string)($_POST[$k]??''));foreach(['education','experience','achievements'] as $k){$x=json_decode((string)($_POST[$k]??'[]'),true);$d[$k]=is_array($x)?$x:[];}if(!W('about',$d))throw new RuntimeException('About JSON saqlanmadi.');$msg='About saqlandi.';$tab='about';}
elseif($a==='expertise'){$d=R('expertise',['intro'=>'','items'=>[]]);$d['intro']=trim((string)($_POST['intro']??''));$x=json_decode((string)($_POST['items']??'[]'),true);$d['items']=is_array($x)?$x:[];if(!W('expertise',$d))throw new RuntimeException('Expertise JSON saqlanmadi.');$msg='Mutaxassislik saqlandi.';$tab='expertise';}
elseif($a==='portfolio'){$d=R('portfolio',['intro'=>'','items'=>[]]);$d['intro']=trim((string)($_POST['intro']??''));$x=json_decode((string)($_POST['items']??'[]'),true);$d['items']=is_array($x)?$x:[];if(!W('portfolio',$d))throw new RuntimeException('Portfolio JSON saqlanmadi.');$msg='Portfolio saqlandi.';$tab='portfolio';}
elseif($a==='status'){$d=R('requests',[]);$id=(string)($_POST['id']??'');$s=(string)($_POST['status']??'new');if(!in_array($s,['new','read','contacted','completed','archived'],true))throw new RuntimeException('Status noto‘g‘ri.');foreach($d as &$r)if(($r['id']??'')===$id)$r['status']=$s;unset($r);W('requests',$d);$msg='So‘rov yangilandi.';$tab='requests';}
elseif($a==='upload'){$f=$_FILES['media']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>50*1024*1024)throw new RuntimeException('Fayl xatosi yoki 50 MB dan katta.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','video/mp4'=>'mp4','video/webm'=>'webm','video/quicktime'=>'mov'];if(!isset($map[$mime]))throw new RuntimeException('Ruxsat etilmagan MIME turi.');$name=bin2hex(random_bytes(16)).'.'.$map[$mime];$dir=$root.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Upload saqlanmadi.');$m=R('media',['items'=>[]]);$m['items'][]=['name'=>$name,'path'=>'uploads/'.$name,'type'=>str_starts_with($mime,'video/')?'video':'image','category'=>trim((string)($_POST['category']??'professional')),'title'=>trim((string)($_POST['title']??'Professional media'))];W('media',$m);$msg='Media yuklandi.';$tab='media';}
}}catch(Throwable $x){$err=$x->getMessage();}
$doctor=R('doctor');$about=R('about');$expertise=R('expertise',['intro'=>'','items'=>[]]);$portfolio=R('portfolio',['intro'=>'','items'=>[]]);$requests=R('requests',[]);$media=R('media',['items'=>[]]);$new=count(array_filter($requests,fn($r)=>($r['status']??'new')==='new'));
function linkx(string $k,string $v,string $tab,int $new):string{return '<a class="'.($k===$tab?'a':'').'" href="?tab='.h($k).'">'.h($v).($k==='requests'&&$new?' · '.$new:'').'</a>';}function sf(string $a):string{return '<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="action" value="'.h($a).'">';}function inp(string $k,string $v,mixed $x):string{return '<label>'.h($v).'<input name="'.h($k).'" value="'.h($x).'" ></label>';}
?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jahongir Neuro — Admin</title><style>:root{--g:#0f5c4d;--s:#e3eeea;--bg:#f4f7f5;--l:#dfe7e3;--m:#71807a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#10201c;font:14px Arial}.layout{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{background:#fff;border-right:1px solid var(--l);padding:22px 14px;position:sticky;top:0;height:100vh}.logo{font-size:18px;font-weight:900;padding:8px 10px 25px}.logo span{color:var(--g)}nav{display:grid;gap:4px}nav a{padding:11px 12px;border-radius:12px;color:#65716d;text-decoration:none}nav a.a,nav a:hover{background:var(--s);color:#174f45;font-weight:700}.main{padding:30px;max-width:1500px;width:100%}.top{display:flex;justify-content:space-between;align-items:center}.top h1{font-size:38px;letter-spacing:-.06em}.logout{color:var(--m)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:#fff;border:1px solid var(--l);border-radius:22px;padding:22px;margin-top:16px}.metric{font-size:34px;font-weight:900;color:var(--g)}.muted,small{color:var(--m)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:grid;gap:7px;margin-bottom:13px;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:11px;border:1px solid #dce4e0;border-radius:12px;background:#fbfcfb;font:inherit;box-sizing:border-box}textarea{min-height:120px}.btn{border:0;background:var(--g);color:#fff;padding:11px 15px;border-radius:12px;font-weight:800;cursor:pointer}.notice{padding:12px;border-radius:13px;background:var(--s);color:#174f45;margin:15px 0}.err{background:#faecec;color:#8b3030}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0ef;text-align:left;vertical-align:top}.media{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:20px}.media article{background:#f8faf9;border:1px solid var(--l);border-radius:16px;overflow:hidden}.media img,.media video{width:100%;height:140px;object-fit:cover;display:block}.media article div{padding:10px}.hint{font-size:12px;color:var(--m);line-height:1.6}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{height:auto;position:relative;border-right:0;border-bottom:1px solid var(--l)}nav{display:flex;overflow:auto}.cards,.media{grid-template-columns:1fr 1fr}}@media(max-width:600px){.main{padding:18px}.cards,.grid,.media{grid-template-columns:1fr}.top h1{font-size:30px}}</style></head><body><div class="layout"><aside class="side"><div class="logo">Jahongir <span>Neuro</span></div><nav><?php foreach($tabs as $k=>$v)echo linkx($k,$v,$tab,$new);?></nav></aside><main class="main"><div class="top"><h1><?=h($tabs[$tab])?></h1><a class="logout" href="?logout=1">Chiqish →</a></div><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=h($err)?></div><?php endif;?>
<?php if($tab==='dashboard'):?><div class="cards"><?php foreach([[count($requests),'Jami so‘rov'],[$new,'Yangi so‘rov'],[count($expertise['items']??[]),'Mutaxassislik'],[count($media['items']??[]),'Media']] as $c):?><div class="card"><div class="metric"><?=$c[0]?></div><div class="muted"><?=$c[1]?></div></div><?php endforeach;?></div>
<?php elseif($tab==='doctor'):?><?=sf('doctor')?><div class="panel"><h2>Doktor</h2><div class="grid"><?php foreach(['name','short_name','title','position','clinic','city','academic_degree','experience'] as $k)echo inp($k,$k,$doctor[$k]??'');?></div><label>Bio<textarea name="bio"><?=h($doctor['bio']??'')?></textarea></label><label>Operations<textarea name="operations"><?=h(implode("\n",$doctor['operations']??[]))?></textarea></label><label>Experience cities<textarea name="experience_cities"><?=h(implode("\n",$doctor['experience_cities']??[]))?></textarea></label><button class="btn">Saqlash</button></div></form>
<?php elseif($tab==='about'):?><?=sf('about')?><div class="panel"><h2>About</h2><?=inp('title','Title',$about['title']??'')?><label>Bio<textarea name="bio"><?=h($about['bio']??'')?></textarea></label><?php foreach(['education','experience','achievements'] as $k):?><label><?=h($k)?><textarea name="<?=$k?>"><?=h(json_encode($about[$k]??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></textarea></label><?php endforeach;?><button class="btn">Saqlash</button></div></form>
<?php elseif($tab==='expertise'):?><?=sf('expertise')?><div class="panel"><h2>Mutaxassislik</h2><label>Intro<textarea name="intro"><?=h($expertise['intro']??'')?></textarea></label><label>Items JSON<textarea name="items"><?=h(json_encode($expertise['items']??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></textarea></label><button class="btn">Saqlash</button></div></form>
<?php elseif($tab==='portfolio'):?><?=sf('portfolio')?><div class="panel"><h2>Portfolio</h2><label>Intro<textarea name="intro"><?=h($portfolio['intro']??'')?></textarea></label><label>Items JSON<textarea name="items"><?=h(json_encode($portfolio['items']??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></textarea></label><p class="hint">Portfolio public sahifasi media.json manifestini ham ko‘rsatadi.</p><button class="btn">Saqlash</button></div></form>
<?php elseif($tab==='requests'):?><div class="panel"><h2>So‘rovlar</h2><div class="tablewrap"><table class="table"><tr><th>ID</th><th>Kontakt</th><th>Xabar</th><th>Status</th></tr><?php foreach($requests as $r):?><tr><td><?=h($r['id']??'')?><br><small><?=h($r['created_at']??'')?></small></td><td><?=h($r['name']??'')?><br><?=h($r['phone']??'')?><br><?=h($r['email']??'')?></td><td><?=h($r['message']??'')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=h($r['id']??'')?>"><select name="status" onchange="this.form.submit()"><?php foreach(['new','read','contacted','completed','archived'] as $s):?><option value="<?=$s?>" <?=($r['status']??'new')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></table></div></div>
<?php elseif($tab==='media'):?><div class="panel"><h2>Media</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="upload"><div class="grid"><label>Fayl<input type="file" name="media" required accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime"></label><?=inp('title','Title','Professional media')?><?=inp('category','Category','professional')?></div><button class="btn">Upload</button></form><div class="media"><?php foreach($media['items']??[] as $m):$src='/'.ltrim((string)($m['path']??'uploads/'.($m['name']??'')),'/');?><article><?php if(($m['type']??'image')==='video'):?><video controls preload="metadata"><source src="<?=h($src)?>"></video><?php else:?><img src="<?=h($src)?>" alt="<?=h($m['title']??'')?>" loading="lazy"><?php endif;?><div><b><?=h($m['title']??$m['name']??'Media')?></b><br><small><?=h($m['category']??'')?></small></div></article><?php endforeach;?></div></div>
<?php elseif($tab==='settings'):?><div class="panel"><h2>Settings</h2><p class="hint"><code>ADMIN_PASSWORD</code> environment variable orqali autentifikatsiya ishlaydi. JSON yozuvlari LOCK_EX bilan saqlanadi. Upload MIME tekshiruvi va 50 MB limitga ega.</p></div><?php endif;?></main></div></body></html>
